list_order_flags.code:
use WebCommander\Sdk\Resources\OrderFlags\OrderFlags;

$response = OrderFlags::listOrderFlags($client, ['limit' => 20]);

foreach ($response->map['order_flags'] as $flag) {
    echo $flag['id'], ' ', $flag['name'], ' ', $flag['color'], PHP_EOL;
}

create_order_flag.code:
use WebCommander\Sdk\Resources\OrderFlags\OrderFlags;

$response = OrderFlags::createOrderFlag($client, [
    'order_flag' => [
        'name' => 'Awaiting Stock',
        'color' => '#5A7BD4',
        'description' => 'Waiting for stock to arrive.',
    ],
]);

echo $response->map['order_flag']['id'], PHP_EOL;

update_order_flag.code:
use WebCommander\Sdk\Resources\OrderFlags\OrderFlags;

$response = OrderFlags::updateOrderFlag($client, 4, [
    'order_flag' => [
        'name' => 'Awaiting Stock',
        'color' => '#B02E2E',
        'description' => 'Waiting for stock from the supplier.',
    ],
]);

echo $response->map['order_flag']['color'], PHP_EOL;
